/**
 * src/build/guides.js — the 22 guide pages, rendered in-process.
 *
 * PHASE 4 STEP 4 — TEMPLATE MIGRATION
 *
 * The other four builders were ports: a legacy script moved into this
 * directory with its behaviour transcribed. This one has no predecessor to
 * port. The guide pages were never generated by anything — they were 22
 * hand-authored files that the pipeline staged, let the header and footer
 * patch, and published. `render` ran four builders and none of them owned a
 * guide page.
 *
 * So this is the first builder to be written rather than moved, and what it
 * replaces is not a script but a copy-paste convention:
 * `docs/archive/_TEMPLATE.html`, whose own instructions were "copy it to
 * guide/your-new-slug.html and fill in every {{PLACEHOLDER}}". That is the
 * convention that produced the drift this step had to record rather than fix
 * — nine pages missing a body class, three missing the toast container, three
 * JSON-LD shapes across 22 pages (F2). A template a human copies is a
 * template that has already forked 22 ways.
 *
 *     content/guide/<slug>.html + pages.json   guide-specific content/data
 *     src/build/guide-template.js              the one page structure
 *     this module                              model -> files
 *     src/build/build.js `render`              the pipeline slot
 *
 * NOT A SECOND PIPELINE
 *
 * This module is a WRITER, exactly like src/build/categories.js: same shape,
 * same slot in `render`, same relationship to the header and footer, same
 * output root. It emits each page's full HTML from scratch, every run, into
 * the staging root, and nothing else in the pipeline changes shape to
 * accommodate it. It has no main(), no CLI and no way to run on its own.
 *
 * WHERE ITS INPUTS COME FROM
 *
 *   ctx.model.guidePages   the page records and their content slots, loaded
 *                          and validated by src/build/content.js in `load`
 *   partials/header.html   read from the repo root, .trim()ed, embedded raw
 *   partials/footer.html   the same
 *
 * THE PARTIALS GO IN RAW, AND THAT IS DELIBERATE
 *
 * Like categories.js, this module embeds the trimmed partial verbatim inside
 * the HEADER_START/END and FOOTER_START/END comments, with no aria-current
 * state. src/build/header.js restores that state afterwards and
 * src/build/footer.js rewrites its own region after that, which is why this
 * module runs before both. The committed pages carried the final, marked-up
 * header, so before this step the header builder had nothing to do on a guide
 * page and reported all 22 as "already current"; now it reports them as
 * updated. The published bytes are the same either way — verified — and the
 * header stops being something 22 files each keep their own copy of.
 *
 * THE OUTPUT ROOT MUST BE THE STAGING ROOT
 *
 * For the same reason categories.js writes there: the header runs next and
 * has to patch these pages, the footer after that, and only then does
 * `render` publish them to dist/. Nothing outside the staging root is
 * written.
 *
 * WHAT THE COMMITTED guide/*.html FILES ARE NOW
 *
 * Generated output that happens to be committed — the same standing the
 * committed category/*.html pages have had since Step 3C. `copy` stages every
 * routed page from the repo root before `render` runs, so they are still
 * read; this module then overwrites every one of them in the staging root, and
 * the published page is this module's output, not the committed file. Keeping
 * them is what makes this step reviewable: guide-template.test.js renders each
 * page and diffs it against the committed file, so the migration is proved
 * against the artefact it migrated rather than against a snapshot of itself.
 * Deleting them means teaching `copy` not to stage a page a writer produces,
 * which changes a shared stage for all 41 routes — a separate step, with its
 * own approval.
 */

"use strict";

const fs = require("fs");
const path = require("path");

const template = require("./guide-template.js");
const head = require("./head.js");
const header = require("./header.js");
const footer = require("./footer.js");

const HEADER_PARTIAL = path.join("partials", "header.html");
const FOOTER_PARTIAL = path.join("partials", "footer.html");

/** Output directory, relative to the staging root. */
const GUIDE_DIR = "guide";

/**
 * The writers emit the four marker comments; header.js and footer.js find
 * them again by their own constants. Two spellings of one contract, and a
 * typo in either fails silently — the marker would simply never match and the
 * page would publish with a raw partial in it. So they are checked against
 * each other on every build instead of being kept in step by comment.
 *
 * PHASE 4 STEP 8 — ONE WRITER SPELLING, AND THE CATEGORY PAGES ARE IN IT NOW
 *
 * There used to be THREE spellings, not two: src/build/guide-template.js
 * declared the four markers, src/build/categories.js wrote the same four as
 * bare literals inside its page template, and header.js/footer.js declared
 * their two each. Only the first was checked, so the pages this check covered
 * were the 22 it was written for and not the 10 that had the same failure
 * mode.
 *
 * Both writers take the markers from src/build/head.js now, so the check below
 * is over one writer spelling and the patchers' — and it covers every page the
 * build writes from scratch. `assertWritersAgree` asserts that consolidation
 * itself, so a future edit cannot quietly reintroduce a private literal in
 * either writer and slip back out of coverage.
 */
function assertMarkersAgree() {
  const pairs = [
    ["HEADER_START", template.HEADER_START, header.START_MARKER],
    ["HEADER_END", template.HEADER_END, header.END_MARKER],
    ["FOOTER_START", template.FOOTER_START, footer.START_MARKER],
    ["FOOTER_END", template.FOOTER_END, footer.END_MARKER],
  ];
  for (const [name, mine, theirs] of pairs) {
    if (mine !== theirs) {
      throw new Error(
        `${name} marker disagrees: src/build/guide-template.js has ` +
          `${JSON.stringify(mine)}, the builder that patches it has ` +
          `${JSON.stringify(theirs)}`,
      );
    }
  }

  for (const name of [
    "HEADER_START",
    "HEADER_END",
    "FOOTER_START",
    "FOOTER_END",
  ]) {
    if (template[name] !== head[name]) {
      throw new Error(
        `${name} marker disagrees: src/build/guide-template.js has ` +
          `${JSON.stringify(template[name])}, src/build/head.js — which ` +
          `src/build/categories.js writes from — has ` +
          `${JSON.stringify(head[name])}`,
      );
    }
  }
}

/**
 * ISSUE #10 — every related-resource link must be a page this build
 * publishes. src/build/content.js resolved each href from resource-types.json
 * or fonts.json; this checks the result against the route table itself, so a
 * landingUrl that drifts from the route it names fails the build instead of
 * shipping a link to a redirect or a 404.
 */
function assertResourcesRouted(pages, routeTable) {
  if (!Array.isArray(routeTable)) {
    throw new Error(
      "ctx.routes is not an array — the guide builder runs after `load`, " +
        "which builds the route table.",
    );
  }
  const urls = new Set(routeTable.map((r) => r.url));
  pages.forEach((page) =>
    (page.resources || []).forEach((r) => {
      if (!urls.has(r.href)) {
        throw new Error(
          `guide-resources.json: guide "${page.id}" links ${r.href}, which ` +
            `is not a route the build publishes`,
        );
      }
    }),
  );
}

/**
 * Writes one page per record in ctx.model.guidePages, into the staging root,
 * from scratch.
 *
 * Every record is written on every run, unconditionally — the same choice
 * categories.js made, for the same reason: a page rendered from scratch has
 * no "already current" state to compare against that the template does not
 * already make deterministic.
 *
 * Returns { written, pages } for the caller to summarize:
 *   written  the file each page was written to, repo-relative
 *   pages    how many records were rendered
 */
function render(ctx) {
  const { root, stage } = ctx.config.paths;

  const pages = ctx.model.guidePages;
  if (!Array.isArray(pages)) {
    throw new Error(
      "ctx.model.guidePages is not an array — the guide builder runs after " +
        "`load` and expects src/build/content.js to have loaded content/guide/.",
    );
  }

  assertMarkersAgree();
  assertResourcesRouted(pages, ctx.routes);

  const partials = {
    header: fs.readFileSync(path.join(root, HEADER_PARTIAL), "utf8").trim(),
    footer: fs.readFileSync(path.join(root, FOOTER_PARTIAL), "utf8").trim(),
  };

  const outDir = path.join(stage, GUIDE_DIR);
  fs.mkdirSync(outDir, { recursive: true });

  const written = [];
  for (const page of pages) {
    const html = template.pageHtml(page, partials);
    fs.writeFileSync(path.join(outDir, `${page.id}.html`), html);
    written.push(`${GUIDE_DIR}/${page.id}.html`);
  }

  return { written, pages: pages.length };
}

module.exports = {
  render,
  assertMarkersAgree,
  assertResourcesRouted,
  HEADER_PARTIAL,
  FOOTER_PARTIAL,
  GUIDE_DIR,
};
